// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * diff — react to a step-state change by running the workflow's diff rules.
 *
 * Rules run in ascending `priority` order; every applicable rule runs (the
 * priority orders side effects, it does not short-circuit).
 *
 * For each rule:
 *   applicability  — 'all', or 'query' gated by applicability_query.$condn
 *                    matched against the instance's task (prompt defers).
 *   selector       — picks candidate steps: forAll / first / firstN(n) /
 *                    group(group_selector) / single(group_selector).
 *   condition      — per step-property checks; "$delta" entries only match the
 *                    step that just changed with the observed before→after.
 *   action.internal— sets step properties on self or other_selector matches.
 *   action.external— queues email/agent side effects on the instance outbox.
 */
import { randomUUID } from 'node:crypto';
import type { DiffRule, RelativeAssignee, SetExpr, StepCondition, StepStateValue, WorkflowDSL } from '../../../dsl/types.ts';
import type { Directory, PromptEvaluator } from './evaluator.ts';
import { deltaToDate, resolveAssignees, type Balancer } from './init.ts';
import { get, matches, substituteObject } from './mongo.ts';
import {
  isMutableStepProperty,
  setStepProperty,
  stepPropertyValue,
  type HistorySource,
  type StepState,
  type WorkflowInstance,
} from './state.ts';

/**
 * Who to credit for a rule-driven write. Rules act as the engine, but always
 * because some human's request set them off — recording that is what makes the
 * audit trail usable for four-eyes review.
 */
export interface Provenance {
  actor?: string;
  source: HistorySource;
  origin_instance_id?: string;
}

export interface StepChange {
  stepId: string;
  /** Property → { before, after } as observed by the patch that triggered diff. */
  changed: Record<string, { before: unknown; after: unknown }>;
}

const isExpr = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

/** "step$status" → "status"; bare names pass through. */
const propOf = (key: string): string => (key.includes('$') ? key.slice(key.indexOf('$') + 1) : key);

function selectSteps(rule: DiffRule, steps: StepState[]): StepState[] {
  const { rule: kind, n, group_selector } = rule.selector;
  // `grouped` is the candidate pool for every kind: when a group_selector is
  // present, first/firstN take the first of the MATCHING steps, not of all
  // steps (which silently fired rules on unrelated steps).
  const grouped = group_selector ? steps.filter((s) => matches(s, group_selector)) : steps;
  switch (kind) {
    case 'forAll':
      return grouped;
    case 'first':
      return grouped.slice(0, 1);
    case 'firstN':
      return grouped.slice(0, n ?? 1);
    case 'group':
      return grouped;
    case 'single':
      return grouped.slice(0, 1);
  }
}

function conditionHolds(
  cond: StepCondition,
  prop: string,
  step: StepState,
  change: StepChange,
): boolean {
  if ('$delta' in cond) {
    if (step.id !== change.stepId) return false;
    const observed = change.changed[prop];
    if (!observed) return false;
    const { before, after } = cond.$delta;
    const want = (expected: unknown, actual: unknown) =>
      expected === '' || expected === undefined || JSON.stringify(expected) === JSON.stringify(actual);
    return want(before, observed.before) && want(after, observed.after);
  }
  const q = cond.$condn;
  if (!isExpr(q)) return true; // placeholder string — vacuous
  return matches({ [prop]: get(step, prop) }, { [prop]: q } as Record<string, unknown>) ||
    matches(get(step, prop) as object, q);
}

function resolveSet(
  expr: SetExpr,
  target: StepState,
  now: Date,
): { set: boolean; value?: unknown; pendingPrompt?: string } {
  if (isExpr(expr.$condn) && !matches(target, expr.$condn)) return { set: false };
  if (expr.value !== undefined && expr.value !== '') {
    let v = expr.value;
    if (isExpr(v) && '$delta' in v) v = deltaToDate(v.$delta as never, now);
    return { set: true, value: v };
  }
  if (expr.prompt) return { set: false, pendingPrompt: expr.prompt };
  return { set: false };
}

/**
 * Re-run a step's assignee query when it enters a state the author marked
 * `reresolve_on`. Called for every state change — a user's PATCH and a rule's
 * set alike — because a send-back is usually the latter, and that is exactly
 * the moment work should stop going to someone who has left.
 *
 * Keeps the existing assignees when the query finds nobody: an empty assignee
 * list would lock the step for everyone, which is worse than a stale one.
 */
/**
 * Walk the org hierarchy relative to another step's holders. `up` reaches
 * managers (escalation), `down` reaches reportees. Returns [] when the chain
 * runs dry, so the caller falls back to the ordinary query rather than leaving
 * a step nobody can action.
 */
export interface OrgHierarchy {
  managers(id: string, businessUnit?: string, organizationId?: string): string[];
  reportees(id: string, businessUnit?: string, organizationId?: string): string[];
}

export function resolveRelative(
  rel: RelativeAssignee,
  instance: WorkflowInstance,
  org: OrgHierarchy,
  directory?: Directory,
): string[] {
  // The anchor: either a step's holders, or whoever the directory says occupies
  // an org position. Exactly one is declared (dsl/validate.ts enforces it), so
  // there is no precedence to settle here.
  let anchor: string[];
  if (rel.from_query) {
    if (!directory) return [];
    const { query, unresolved } = substituteObject(rel.from_query, instance.object.data);
    // Same fail-closed rule as the assignee query: an anchor that cannot be
    // pinned down must resolve to nobody, not to everyone holding the role.
    if (unresolved.length > 0) return [];
    anchor = directory
      .query(query as Record<string, unknown>, Infinity, instance.organization_id)
      .map((u) => u.id);
  } else {
    if (!instance.steps.some((s) => s.id === rel.from_step)) return [];
    anchor = instance.steps.find((s) => s.id === rel.from_step)!.assignee;
  }
  if (anchor.length === 0) return [];
  const bu = instance.task.business_unit as string | undefined;
  const walk = rel.direction === 'down'
    ? (id: string) => org.reportees(id, bu, instance.organization_id)
    : (id: string) => org.managers(id, bu, instance.organization_id);
  let rung = anchor;
  for (let i = 0; i < (rel.levels ?? 1); i++) {
    const next = [...new Set(rung.flatMap(walk))];
    if (next.length === 0) return []; // ran out of chain
    rung = next;
  }
  // never hand the step back to the people it is resolved relative to
  return rung.filter((id) => !anchor.includes(id));
}

export function reresolveOnEnter(
  step: StepState,
  dsl: WorkflowDSL,
  directory: Directory,
  instance: WorkflowInstance,
  at: string,
  prov: Provenance,
  balancer?: Balancer,
  org?: OrgHierarchy,
): void {
  const spec = dsl.init.steps.find((t) => t.id === step.id)?.assignee;
  if (!spec?.reresolve_on?.includes(step.state)) return;
  // a human placed this deliberately; re-running the query would undo it, and
  // where two steps share a query that silently rejoins maker and checker
  if (step.assignee_pinned) return;
  // a relative assignee is the whole point of entering: it reads another step's
  // holder, which is only settled once the work has reached here
  const relative = spec.relative && org ? resolveRelative(spec.relative, instance, org, directory) : [];
  const { ids } = relative.length
    ? { ids: relative.slice(0, spec.limit ?? 1) }
    : resolveAssignees(
        spec,
        directory,
        [],
        balancer,
        `${instance.organization_id}:${instance.workflow_id}:${step.id}`,
        instance.organization_id,
        instance.object.data,
      );
  if (ids.length === 0 || JSON.stringify(ids) === JSON.stringify(step.assignee)) return;
  const before = step.assignee;
  step.assignee = ids;
  instance.history.push({
    at,
    type: 'assignee_reresolved',
    step_id: step.id,
    detail: `entered "${step.state}": ${JSON.stringify(before)} → ${JSON.stringify(ids)}`,
    data: { before, after: ids, reason: relative.length ? 'relative' : 'reresolve_on' },
    ...prov,
  });
}

/** Applies one matched rule's internal/external actions to `instance` (shared by runDiff and runCohortRules). */
function applyRuleActions(
  rule: DiffRule,
  matched: StepState[],
  instance: WorkflowInstance,
  directory: Directory,
  now: Date,
  at: string,
  dsl: WorkflowDSL,
  prov: Provenance,
  balancer?: Balancer,
  org?: OrgHierarchy,
): void {
  for (const self of matched) {
    const internal = rule.action.internal;
    if (internal) {
      const targets =
        internal.scope === 'self'
          ? [self]
          : instance.steps.filter((s) => matches(s, internal.other_selector ?? {}));
      for (const target of targets) {
        for (const [prop, expr] of Object.entries(internal.set ?? {})) {
          const res = resolveSet(expr, target, now);
          if (res.pendingPrompt) {
            instance.pending_prompts[`steps.${target.id}.${prop}`] = res.pendingPrompt;
          }
          if (!res.set) continue;
          // The transition matrix binds the workflow's own rules too —
          // otherwise it constrains humans while the author's automation
          // walks straight through it (including out of a terminal state).
          if (prop === 'state') {
            const err = transitionError(dsl, target.state, res.value as string);
            if (err) {
              instance.history.push({
                at,
                type: 'internal_set',
                step_id: target.id,
                detail: `skipped by init.transitions (rule p${rule.priority}): ${err}`,
                ...prov,
              });
              continue;
            }
          }
          if (!isMutableStepProperty(prop)) continue;
          const before = stepPropertyValue(target, prop);
          if (!setStepProperty(target, prop, res.value)) continue;
          instance.history.push({
            at,
            type: 'internal_set',
            step_id: target.id,
            detail: `${prop} ← ${JSON.stringify(res.value)} (rule p${rule.priority})`,
            ...prov,
          });
          // A rule can land an approval; the approval log must show it, or a
          // workflow author could move a checker step with the maker's request
          // and leave nothing in the "who decided" view.
          // Becoming actionable counts as entering the step. A dormant step's
          // assignee was resolved at attach — possibly long before — so without
          // this, `reresolve_on` is inert for exactly the steps that wait, and
          // a `relative` assignee could never see the holder it points at.
          if (prop === 'status' && res.value === true && before !== true) {
            reresolveOnEnter(target, dsl, directory, instance, at, prov, balancer, org);
          }
          if (prop === 'state' && before !== res.value) {
            instance.history.push({
              at,
              type: 'state_changed',
              step_id: target.id,
              detail: `${before} → ${res.value} (rule p${rule.priority})`,
              data: { before, after: res.value },
              ...prov,
            });
            reresolveOnEnter(target, dsl, directory, instance, at, prov, balancer, org);
          }
        }
      }
    }

    const external = rule.action.external;
    if (external?.email) {
      const { prompt, query } = external.email.recipients.$or;
      const recipients =
        query && isExpr(query)
          ? directory.query(query, undefined, instance.organization_id).map((u) => u.email ?? u.id)
          : { pending_prompt: prompt ?? '' };
      instance.outbox.push({
        kind: 'email',
        rule_priority: rule.priority,
        step_id: self.id,
        recipients,
        subject: external.email.subject?.value?.toString() || external.email.subject?.prompt,
        body: external.email.body?.value?.toString() || external.email.body?.prompt,
        attachments: external.email.attachments,
        delivery: { id: randomUUID(), status: 'pending', attempts: 0, next_attempt_at: at },
      });
      instance.history.push({ at, type: 'external_queued', step_id: self.id, detail: 'email', ...prov });
    }
    for (const agent of external?.agent ?? []) {
      instance.outbox.push({
        kind: 'agent',
        rule_priority: rule.priority,
        step_id: self.id,
        agent_id: agent._id,
        name: agent.name,
        prompt: agent.prompt,
        state: agent.state,
        delivery: { id: randomUUID(), status: 'pending', attempts: 0, next_attempt_at: at },
      });
      instance.history.push({
        at,
        type: 'external_queued',
        step_id: self.id,
        detail: `agent:${agent.name}`,
        ...prov,
      });
    }
  }
}

/**
 * Aggregate test over a pool: every member must match `all`, or — when
 * `min_matching` is set — at least that many must (quorum). An empty pool
 * never satisfies a guard.
 */
export function poolSatisfies(
  pool: StepState[],
  all: Record<string, unknown>,
  minMatching?: number,
): boolean {
  if (pool.length === 0) return false;
  const hits = pool.filter((s) => matches(s, all)).length;
  return minMatching === undefined ? hits === pool.length : hits >= minMatching;
}

/** `once: true` rules fire at most one time per instance (see DiffRule.once). */
function alreadyFired(rule: DiffRule, instance: WorkflowInstance): boolean {
  return rule.once === true && (instance.fired_once ?? []).includes(rule.priority);
}

function recordFired(rule: DiffRule, instance: WorkflowInstance): void {
  if (rule.once !== true) return;
  instance.fired_once = [...(instance.fired_once ?? []), rule.priority];
}

/** Fire only if the steps matching guard.selector satisfy guard.all (all, or a quorum). */
function guardHolds(rule: DiffRule, instance: WorkflowInstance): boolean {
  if (!rule.guard) return true;
  const pool = instance.steps.filter((s) => matches(s, rule.guard!.selector));
  return poolSatisfies(pool, rule.guard.all, rule.guard.min_matching);
}

/**
 * Enforce init.transitions. Returns an error message when `from → to` is not
 * permitted, or null when it is (including when no matrix is declared).
 * Once a matrix exists it is the whole contract: a state with no entry has no
 * legal exits, so a partially-declared matrix cannot leave silent holes.
 */
export function transitionError(
  dsl: WorkflowDSL,
  from: string,
  to: string,
): string | null {
  const matrix = dsl.init.transitions;
  if (!matrix || from === to) return null;
  const allowed = matrix[from as StepStateValue];
  if (allowed?.includes(to as StepStateValue)) return null;
  return (
    `transition ${from} → ${to} is not allowed by init.transitions ` +
    (allowed?.length ? `(allowed: ${allowed.join(', ')})` : `("${from}" is terminal)`)
  );
}

/** Author-declared instance completion (init.terminal_when); false when undeclared. */
export function isTerminal(dsl: WorkflowDSL, instance: WorkflowInstance): boolean | undefined {
  const t = dsl.init.terminal_when;
  if (!t) return undefined; // the workflow declares no completion condition
  return poolSatisfies(instance.steps.filter((s) => matches(s, t.selector)), t.all, t.min_matching);
}

export async function runDiff(
  instance: WorkflowInstance,
  dsl: WorkflowDSL,
  change: StepChange,
  directory: Directory,
  evaluator: PromptEvaluator,
  now = new Date(),
  actor?: string,
  balancer?: Balancer,
  org?: OrgHierarchy,
): Promise<void> {
  const prov: Provenance = { actor, source: 'rule' };
  const rules = [...dsl.diff].sort((a, b) => a.priority - b.priority);
  const at = now.toISOString();

  for (const rule of rules) {
    if (rule.cohort_guard) continue; // evaluated by runCohortRules, never per-instance
    if (rule.applicability === 'query') {
      const gate = rule.applicability_query;
      if (!gate) continue;
      if (isExpr(gate.$condn)) {
        if (!matches(instance.task, gate.$condn)) continue;
      } else if (gate.value !== undefined && gate.value !== '') {
        if (!gate.value) continue;
      } else if (gate.prompt) {
        const verdict = await evaluator.evaluate(gate.prompt, { task: instance.task });
        if (verdict === undefined) {
          instance.pending_prompts[`diff.p${rule.priority}.applicability`] = gate.prompt;
          continue;
        }
        if (!verdict) continue;
      }
    }

    const entries = Object.entries(rule.condition).map(
      ([key, cond]) => [propOf(key), cond] as const,
    );
    const matched = selectSteps(rule, instance.steps).filter((step) =>
      entries.every(([prop, cond]) => conditionHolds(cond, prop, step, change)),
    );
    if (matched.length === 0) continue;
    if (!guardHolds(rule, instance)) continue;
    if (alreadyFired(rule, instance)) continue;
    recordFired(rule, instance);

    instance.history.push({
      at,
      type: 'diff_rule_fired',
      detail: `priority ${rule.priority}`,
      data: { steps: matched.map((s) => s.id) },
      ...prov,
    });

    applyRuleActions(rule, matched, instance, directory, now, at, dsl, prov, balancer, org);
  }
  instance.updated_at = at;
}

/**
 * Cross-instance pass: after `changed` was patched, re-evaluate every rule
 * carrying a `cohort_guard` on every instance sharing task[join_on] with the
 * changed instance. The guard pools steps matching `cohort_guard.steps` from
 * the cohort (siblings filtered by `cohort_guard.instances`, the watcher
 * excluded) and passes when the pool is non-empty and every pooled step
 * matches `cohort_guard.all`. Returns the instances it mutated.
 *
 * A step patch never treats the changed instance as its own watcher: cohort
 * rules react to sibling changes there (own-step changes are runDiff's
 * domain). A task-membership edit may opt in to self-watching because moving a
 * watcher is itself the event that must re-evaluate its new cohort.
 */
export function runCohortRules(
  instances: WorkflowInstance[],
  dslOf: (instance: WorkflowInstance) => WorkflowDSL | undefined,
  changed: WorkflowInstance,
  directory: Directory,
  now = new Date(),
  actor?: string,
  balancer?: Balancer,
  options: { includeChangedWatcher?: boolean; idempotencyKey?: string } = {},
): WorkflowInstance[] {
  // cohort writes name the instance whose change reached in
  const prov: Provenance = { actor, source: 'cohort', origin_instance_id: changed.id };
  const touched = new Set<WorkflowInstance>();
  const at = now.toISOString();
  const noChange: StepChange = { stepId: '', changed: {} };
  // Deterministic order: watcher rules can cascade into one another, and
  // store iteration order is registration order — which would make identical
  // inputs produce different outcomes depending on attach sequence.
  const ordered = instances
    .filter((instance) => instance.organization_id === changed.organization_id)
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));

  for (const watcher of ordered) {
    if (watcher.id === changed.id && !options.includeChangedWatcher) continue;
    if (
      options.idempotencyKey &&
      (watcher.processed_callback_events ?? []).includes(options.idempotencyKey)
    ) continue;
    const dsl = dslOf(watcher);
    if (!dsl) continue;
    const rules = dsl.diff
      .filter((r) => r.cohort_guard)
      .sort((a, b) => a.priority - b.priority);

    for (const rule of rules) {
      const cg = rule.cohort_guard!;
      // Join keys are identifiers: compare by value, not by JS type, so a
      // batch_id of 1 and "1" do not silently split one cohort in two.
      // Primitives compare by value (so 1 and "1" are one cohort); objects and
      // arrays are serialized rather than String()'d, which would collapse
      // every object join value to "[object Object]" and merge unrelated
      // cohorts into one.
      const joinKey = (i: WorkflowInstance): string | undefined => {
        const v = (i.task as Record<string, unknown>)[cg.join_on];
        if (v === undefined || v === null) return undefined;
        return typeof v === 'object' ? `json:${JSON.stringify(v)}` : String(v);
      };
      const joinVal = joinKey(watcher);
      if (joinVal === undefined) continue;
      if (joinKey(changed) !== joinVal) continue;
      if (rule.applicability === 'query') {
        const gate = rule.applicability_query;
        if (!gate || !isExpr(gate.$condn) || !matches(watcher.task, gate.$condn)) continue;
      }

      const cohort = ordered.filter(
        (i) => i.id !== watcher.id && joinKey(i) === joinVal && matches(i, cg.instances ?? {}),
      );
      const pool = cohort.flatMap((i) => i.steps.filter((s) => matches(s, cg.steps)));
      if (!poolSatisfies(pool, cg.all, cg.min_matching)) continue;

      const entries = Object.entries(rule.condition).map(
        ([key, cond]) => [propOf(key), cond] as const,
      );
      const matched = selectSteps(rule, watcher.steps).filter((step) =>
        entries.every(([prop, cond]) => conditionHolds(cond, prop, step, noChange)),
      );
      if (matched.length === 0) continue;
      if (!guardHolds(rule, watcher)) continue;
      if (alreadyFired(rule, watcher)) continue;
      recordFired(rule, watcher);

      watcher.history.push({
        at,
        type: 'diff_rule_fired',
        detail: `priority ${rule.priority} (cohort:${cg.join_on}=${String(joinVal)})`,
        data: { steps: matched.map((s) => s.id) },
        ...prov,
      });
      applyRuleActions(rule, matched, watcher, directory, now, at, dsl, prov, balancer);
      watcher.updated_at = at;
      touched.add(watcher);
    }
    if (options.idempotencyKey && touched.has(watcher)) {
      watcher.processed_callback_events = [
        ...(watcher.processed_callback_events ?? []),
        options.idempotencyKey,
      ];
    }
  }
  return [...touched];
}
